const stripCite=(t)=>String(t||'').replace(/[-]/g,'').replace(/cite(turn\d+\w+?\d+)+/gi,'').replace(/turn\d+(?:view|search|news|image|video|product|ref)\d+/gi,'').replace(/cite/gi,'').replace(/ {2,}/g,' ').trim();
const stripEmoji=(t)=>String(t||'').replace(/:[a-z0-9_+-]+:/gi,'').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{2190}-\u{21FF}\u{2300}-\u{23FF}\u{FE0F}\u{200D}]/gu,'').replace(/ {2,}/g,' ').trim();
const q=$input.first().json.output||{};
const n=$('Alta Normalize').first().json;
const gptPhone=stripCite(q.phone||'').replace(/[^\d+]/g,'').trim();
const phone=gptPhone||'';
const brief=stripCite(q.slack_brief_markdown).slice(0,2800);
const vlabel=({strong:'Qualified',medium:'Qualified (medium confidence)',weak:'Qualified (weak fit)',out_of_icp:'Not qualified'})[q.qualification_status]||'Needs review';
const vreason=stripEmoji(stripCite(q.verdict_reason||'')).slice(0,200);
const verdict_line=vlabel+' — '+(vreason||'see brief');
const brief_plain=(verdict_line+'\n\n'+stripEmoji(brief)).slice(0,2800);
return [{ json: {
  lead_email:n.lead_email, first_name:n.first_name, company_name:q.company_name||n.company_name,
  reply_text:n.reply_text, reply_channel:n.reply_channel, source_channel:n.source_channel,
  conversation_thread:n.conversation_thread,
  campaign_name:n.campaign_name, alta_campaign_id:n.alta_campaign_id,
  custom_qualification_brief:brief, brief_plain:brief_plain,
  custom_qualification_status:q.qualification_status||'',
  situation_summary:stripCite(q.situation_summary||'').slice(0,200),
  verdict_reason:vreason,
  custom_phone:phone, custom_timezone:q.timezone||'',
  recommended_action:stripCite(q.recommended_action||'').slice(0,300)
}}];

const F = $('Flatten').first().json;
const N = $('Alta Normalize').first().json;
let phoneVal = '', phoneSrc = '';
try { const rp = $('Resolve Phone').first().json || {}; phoneVal = String(rp.phone || '').trim(); phoneSrc = String(rp.phone_source || '').trim(); } catch (e) {}
let B = {};
try { B = $('DiscoLike BizData').first().json || {}; } catch (e) { B = {}; }
let C = {};
try { C = $('Resolve Campaign').first().json || {}; } catch (e) { C = {}; }
let dash = '';
try { dash = String(((($('Get Client Row').first().json || {}).fields) || {})['Dashboard Page ID'] || '').trim(); } catch (e) { dash = ''; }
const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clean = (v) => { const s = String(v == null ? '' : v).trim(); return (!s || s.toUpperCase() === 'N/A') ? '' : esc(s); };
const isUuid = (s) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(s || ''));

const companyRaw = F.company_name || N.company_name || 'Unknown';
const tzRaw = String(F.custom_timezone || '').trim();
const tz = clean(tzRaw);
const zmap = {ET:'America/New_York',CT:'America/Chicago',MT:'America/Denver',PT:'America/Los_Angeles',AT:'America/Halifax',AKT:'America/Anchorage',HT:'Pacific/Honolulu',IL:'Asia/Jerusalem',GMT:'Europe/London',BST:'Europe/London','GMT/BST':'Europe/London',CET:'Europe/Berlin',CEST:'Europe/Berlin',AEST:'Australia/Sydney',IST:'Asia/Kolkata'};
let localTime = '';
try { localTime = $now.setZone(zmap[tzRaw] || 'UTC').toFormat('HH:mm'); } catch (e) { localTime = ''; }

const name = clean(N.full_name);
const title = clean(N.job_title);
const contact = clean(N.lead_email) || clean(N.linkedin_url);

let phoneLine = '_no number found_';
if (phoneVal) {
  const p = esc(phoneVal);
  if (phoneSrc === 'signature') phoneLine = p + '   ✅ _direct line, from their signature_';
  else if (['supersoniq', 'ai-ark', 'leadmagic', 'prospeo', 'LeadMagic'].includes(phoneSrc)) phoneLine = p + '   ✅ _mobile_';
  else if (phoneSrc.endsWith('-tollfree')) phoneLine = p + '   ⚠️ _switchboard, you will get a receptionist_';
  else phoneLine = p;
}

const who = [];
who.push(name ? ('*' + name + '*' + (title ? '   ' + title : '')) : '*General inbox*   confirm the decision maker');
if (contact) who.push(contact);
who.push(phoneLine);
who.push('');
who.push('via Alta · ' + (clean(F.source_channel) || clean(F.reply_channel) || 'reply'));
const place = [clean(N.city), tz, localTime ? localTime + ' their time' : ''].filter(Boolean).join('   ·   ');
if (place) who.push(place);
const firmo = [clean(B.employees) || clean(N.company_size) ? (clean(B.employees) || clean(N.company_size)) + ' staff' : '', clean(B.revenue_range) || clean(N.company_revenue), clean(N.domain)].filter(Boolean).join('   ·   ');
if (firmo) who.push(firmo);

const reply = esc(String(F.reply_text || '').replace(/\s+/g, ' ').trim().slice(0, 900));
const quoted = reply ? '> ' + reply : '> _interested, see thread_';
const brief = esc(String(F.custom_qualification_brief || '').trim());

const blocks = [{ type: 'header', text: { type: 'plain_text', text: ('🔥 new interested qualified lead · ' + companyRaw).slice(0, 150), emoji: true } }];
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: who.join('\n').slice(0, 2900) } });
blocks.push({ type: 'divider' });
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*THEY SAID*\n\n' + quoted).slice(0, 2900) } });
if (brief) {
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*WHY THEY QUALIFY*\n\n' + brief).slice(0, 2900) } });
}

let campName = clean(C.campaignName) || clean(N.campaign_name);
if (!campName) { const cid = String(N.alta_campaign_id || '').trim(); if (cid && !isUuid(cid)) campName = clean(cid); }
if (campName) {
  const statBits = [];
  if (C.contacted) statBits.push(esc(C.contacted) + ' contacted');
  if (C.replies !== '' && C.replies != null) statBits.push(esc(C.replies) + ' replies' + (C.replyRate ? ' (' + esc(C.replyRate) + ')' : ''));
  if (C.positives !== '' && C.positives != null) statBits.push(esc(C.positives) + ' positive' + (C.positiveRate ? ' (' + esc(C.positiveRate) + ')' : ''));
  if (C.status) statBits.push(esc(C.status));
  const campLines = ['*WHERE THEY CAME FROM*', '', campName];
  if (statBits.length) campLines.push(statBits.join('   ·   '));
  if (dash && C.campaignRowId) {
    try {
      const blob = JSON.stringify({ pageId: 'pagnDARjFPzq5HclC', rowId: C.campaignRowId });
      const b64 = Buffer.from(blob, 'utf8').toString('base64').replace(/=+$/, '');
      campLines.push('');
      campLines.push('🔗  *<https://airtable.com/appQG6dK0FIOhTxOl/' + dash + '?detail=' + b64 + '|View the campaign>*  copy and live stats');
    } catch (e) {}
  }
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: campLines.join('\n').slice(0, 2900) } });
}

return [{ json: { blocksJson: JSON.stringify({ blocks }) } }];

const sd2=$getWorkflowStaticData('global'); const rs=sd2.runStartedAt||0;
const n=$('Alta Normalize').first().json;
const cv=$('Client Vars').first().json;
const name=(n.full_name||'').trim();
const base={
 'Automation':'Handle New Lead from Alta',
 'Client': cv.clientRecId?[cv.clientRecId]:[cv.clientName||''],
 'Run at': $now.toISO(),
 'Records In': 1,
 'Records Out': 1,
 'Target': n.lead_email||n.linkedin_url||'',
 'Trigger':'event',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Duration s': Math.round(($now.toMillis() - (rs||$now.toMillis()))/1000)
};
const leadLine='- **Lead:** '+(name?name+' ':'')+'<'+(n.lead_email||n.linkedin_url||'')+'>'+(n.job_title?', '+n.job_title:'');
const companyLine='- **Company:** '+(n.company_name||'unknown')+(n.domain?' ('+n.domain+')':'');
let f=null; try{ f=$('Flatten').first().json; }catch(e){}
if(!f){
 // Reached from an early exit: either Lead in CRM? yes (thread appended) or Interested? no.
 let threadRow=null; try{ threadRow=$('Update Prospect Thread').first().json||null; }catch(e){}
 if(threadRow){
  let exId=threadRow.id||'';
  if(!exId){ try{ exId=$('Find CRM Prospect').first().json.id||''; }catch(e){} }
  const failed=[];
  if(!threadRow.id) failed.push('thread not appended');
  let desc=[
  '**Existing prospect, thread appended**',
  '',
  leadLine,
  companyLine,
  '- **Outcome:** existing prospect'+(exId?' ('+exId+')':'')+', conversation thread appended; re-qualification and Slack post skipped'
  ].join('\n');
  if(failed.length) desc+='\n\n**FAILED ('+failed.length+')**\n'+failed.map(x=>'- '+x).join('\n');
  return [{json:Object.assign({'Status':failed.length?'Succeeded with errors':'Succeeded','Errors':failed.length,'Description':desc},base)}];
 }
 let screenVerdict='';
 try{ const s=$('Screen Reply').first().json; screenVerdict=(s&&s.output&&s.output.verdict)||''; }catch(e){}
 const desc=[
 '**Not interested, skipped**',
 '',
 leadLine,
 companyLine,
 '- **Outcome:** not interested, skipped (screen verdict: '+(screenVerdict||'unknown')+'); no CRM writes, no Slack post'
 ].join('\n');
 return [{json:Object.assign({'Status':'Succeeded','Errors':0,'Description':desc},base)}];
}
let prospectId='';
try{prospectId=$('Create CRM Prospect').first().json.id||'';}catch(e){}
let verdictWritten=false;
try{const v=$('Set CRM Verdict').first().json; if(v&&v.id){verdictWritten=true;}}catch(e){}
let tsWritten=false;
try{const t=$('Set Thread TS').first().json; if(t&&t.id){tsWritten=true;}}catch(e){}
let phoneVal=''; let phoneSource='none';
try{ const rp=$('Resolve Phone').first().json; phoneVal=rp.phone||''; phoneSource=rp.phone_source||'none'; }catch(e){}
const verdict=f.custom_qualification_status||'unknown';
const qualified=verdict!=='out_of_icp';
const campaign=(n.campaign_name?n.campaign_name+(n.alta_campaign_id?' ('+n.alta_campaign_id+')':''):(n.alta_campaign_id||'unknown'));
const failed=[];
if(!prospectId) failed.push('prospect not created');
if(!verdictWritten) failed.push('verdict not written');
if(qualified && !tsWritten) failed.push('thread ts not saved');
let desc=[
'**'+(f.company_name||n.company_name||n.lead_email||'unknown')+' · '+verdict+'**',
'',
leadLine,
'- **Company:** '+(f.company_name||n.company_name||'unknown')+(n.domain?' ('+n.domain+')':''),
'- **Channel:** Alta '+(n.source_channel||n.reply_channel||'reply')+' | Campaign: '+campaign,
'- **Verdict:** '+verdict+(f.verdict_reason?' ('+f.verdict_reason+')':'')+(f.recommended_action?' | Recommended: '+f.recommended_action:''),
'- **Phone:** '+(phoneVal||'Not found')+' (source: '+phoneSource+')',
'- **CRM:** Prospects row created'+(prospectId?' ('+prospectId+')':'')+', contact row + qualification brief + conversation thread written',
'- **Pipeline:** '+(verdictWritten?('set from verdict "'+verdict+'" (Positive Reply / Disqualified)'):'not written'),
'- **Slack:** qualification brief posted to client channel '+(cv.slackChannel||'')+(tsWritten?', thread ts written to prospect':'')
].join('\n');
if(failed.length) desc+='\n\n**FAILED ('+failed.length+')**\n'+failed.map(x=>'- '+x).join('\n');
return [{json:Object.assign({'Status':failed.length?'Succeeded with errors':'Succeeded','Errors':failed.length,'Description':desc},base)}];

let f=null; try{ f=$('Flatten').first().json; }catch(e){}
if(!f) return [];
const cv=$('Client Vars').first().json||{};
let n={}; try{ n=$('Alta Normalize').first().json||{}; }catch(e){}
let prospectId=''; try{ prospectId=$('Create CRM Prospect').first().json.id||''; }catch(e){}
let ts=''; try{ ts=$('Slack Client Channel').first().json.ts||''; }catch(e){}
let phone=''; try{ phone=$('Resolve Phone').first().json.phone||''; }catch(e){}
return [{ json: {
  recordId: cv.clientRecId||'',
  clientSlug: cv.clientSlug||'',
  prospectId: prospectId,
  lead_email: n.lead_email||'', first_name: n.first_name||'', full_name: n.full_name||'',
  company_name: f.company_name||'', verdict: f.custom_qualification_status||'',
  verdict_reason: f.verdict_reason||'',
  slack_brief_markdown: f.custom_qualification_brief||'',
  situation_summary: f.situation_summary||'',
  recommended_action: f.recommended_action||'',
  phone: phone, timezone: f.custom_timezone||'',
  reply_text: f.reply_text||'', city: n.city||'',
  source_channel: n.source_channel||'', reply_channel: n.reply_channel||'',
  campaign_id: n.alta_campaign_id||'', campaign_name: n.campaign_name||'',
  linkedin_url: n.linkedin_url||'',
  core_slack_ts: ts
}}];

// Decides whether to fire the Waterfall Phones webhook for this lead.
// The waterfall owns the phone write on the contact row; this run only needs
// the resolved number back for the Slack cards and the run log.
// Out-of-ICP leads never trigger paid tiers: they fire only when a direct
// signature number is already in hand (free, instant hit inside the waterfall).
const f = $('Flatten').first().json;
let contactId = '';
try { contactId = $('Create CRM Contact').first().json.id || ''; } catch (e) {}
if (!contactId) {
  try {
    const pf = $('Find CRM Prospect').first().json.fields || {};
    const c = pf.Contacts;
    if (Array.isArray(c) && c.length) contactId = String(c[0] && c[0].id ? c[0].id : c[0]);
  } catch (e) {}
}
let sig = '', sigTf = '';
try { const ft = $('Format Thread').first().json || {}; sig = String(ft.signature_phone || '').trim(); sigTf = String(ft.signature_phone_tollfree || '').trim(); } catch (e) {}
const outOfIcp = f.custom_qualification_status === 'out_of_icp';
const _call = (contactId && (!outOfIcp || sig)) ? 1 : 0;
let reason = '';
if (!contactId) reason = 'no contact row';
else if (outOfIcp && !sig) reason = 'out_of_icp';
return [{ json: { _call, contactId, sig: sig || sigTf, sigIsTF: !sig && !!sigTf, reason } }];

// Parses the Waterfall Phones response back into the shape every downstream
// reader expects ({phone, phone_source}). The waterfall (HTNr5G6vBVkbxsqF) owns
// the tier logic AND the phone write on the contact row; this node only carries
// the verdict forward for the Slack cards, the run log, and the addon payload.
const prep = $('Waterfall Prep').first().json;
const out = { phone: '', phone_source: 'none' };
if (prep._call) {
  const r = $input.first().json;
  let b = r && r.body !== undefined ? r.body : r;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = null; } }
  if (b && b.phone !== undefined) {
    out.phone = String(b.phone || '');
    out.phone_source = String(b.phone_source || 'none');
  } else {
    // Waterfall unreachable (inactive, timeout, non-JSON): the lead still flows,
    // the phone just stays unresolved. Surfaced in the run log as 'error'.
    out.phone_source = 'error';
  }
} else if (prep.sig) {
  out.phone = prep.sig;
  out.phone_source = prep.sigIsTF ? 'signature-tollfree' : 'signature';
} else if (prep.reason === 'out_of_icp') {
  out.phone_source = 'skipped';
}
return [{ json: out }];

let id='', row=null;
try{ const f=$('Search Campaign').first(); if(f&&f.json&&f.json.id){ id=f.json.id; row=f.json; } }catch(e){}
if(!id){ try{ const c=$('Create Campaign Row').first(); if(c&&c.json&&c.json.id){ id=c.json.id; row=c.json; } }catch(e){} }
const g=(k)=>{ try{ if(!row) return ''; if(row[k]!=null) return row[k]; if(row.fields&&row.fields[k]!=null) return row.fields[k]; }catch(e){} return ''; };
return [{ json: {
  campaignRowId: id,
  campaignName: g('Campaign'),
  contacted: g('Contacted'),
  replies: g('Replies'),
  replyRate: g('Reply Rate'),
  positives: g('Positive Replies (CRM)'),
  positiveRate: g('Positive Rate'),
  status: (function(){ const s=g('Status'); return (s&&typeof s==='object')?(s.name||''):s; })()
} }];

const p=$input.first().json||{};
const f=p.fields||p;
const n=$('Alta Normalize').item.json||{};
const b=$('Capture Payload').first().json.body||{};
const prev=String(f['Conversation Thread']||'').trim();
const fmtTs=(ts)=>{const d=new Date(ts);if(isNaN(d.getTime()))return '';return d.toLocaleString('sv-SE',{timeZone:'Asia/Jerusalem'}).slice(0,16)+' IL';};
const line='**['+fmtTs(n.first_engagement)+'] THEM:**\n'+(n.reply_text||'');
